		var bSpeedB = nd(1);
		var bbCost = nd(100);
		
		this.addEventListener("tick", mainHome.bind(this));
		function mainHome() {
			
		
			bbCost = nd(100).pow(nd(2).pow(nd(bProgress).pow(0.6)));
			bSpeedB = nd(1).plus(nd(0.1).times(bProgress));
			this.buildWindow.bCost.text = ": " + format(bbCost);
			this.buildWindow.bsBonus.text = "Buildings Speed Bonus: x" + format(bSpeedB);
			
			
			
			if (bProgress == 0) {
				this.buildWindow.house_build.gotoAndStop(0);
				this.buildWindow.cover.gotoAndStop(0);
				this.buildWindow.miska.gotoAndStop(0);
				this.buildWindow.tree1.gotoAndStop(0);
				this.buildWindow.tree2.gotoAndStop(0);
				
				this.buildWindow.house_build.visible = false;
				this.buildWindow.cover.visible = false;
				this.buildWindow.miska.visible = false;
				this.buildWindow.tree1.visible = false;
				this.buildWindow.tree2.visible = false;
			}
			else if (bProgress == 1) {
				this.buildWindow.house_build.gotoAndStop(0);
				this.buildWindow.cover.gotoAndStop(0);
				this.buildWindow.miska.gotoAndStop(0);
				this.buildWindow.tree1.gotoAndStop(0);
				this.buildWindow.tree2.gotoAndStop(0);
				
				this.buildWindow.house_build.visible = true;
				this.buildWindow.cover.visible = false;
				this.buildWindow.miska.visible = false;
				this.buildWindow.tree1.visible = false;
				this.buildWindow.tree2.visible = false;
			}
			else if (bProgress <= 11) {
				this.buildWindow.house_build.gotoAndStop(bProgress - 1);
				this.buildWindow.cover.gotoAndStop(0);
				this.buildWindow.miska.gotoAndStop(0);
				this.buildWindow.tree1.gotoAndStop(0);
				this.buildWindow.tree2.gotoAndStop(0);
				
				this.buildWindow.house_build.visible = true;
				this.buildWindow.cover.visible = false;
				this.buildWindow.miska.visible = false;
				this.buildWindow.tree1.visible = false;
				this.buildWindow.tree2.visible = false;
			}
			else if (bProgress == 12) {
				this.buildWindow.house_build.gotoAndStop(11 + homeSkin);
				this.buildWindow.cover.gotoAndStop(0);
				this.buildWindow.miska.gotoAndStop(0);
				this.buildWindow.tree1.gotoAndStop(0);
				this.buildWindow.tree2.gotoAndStop(0);
				
				this.buildWindow.house_build.visible = true;
				this.buildWindow.cover.visible = false;
				this.buildWindow.miska.visible = false;
				this.buildWindow.tree1.visible = false;
				this.buildWindow.tree2.visible = false;
			}
			else if (bProgress == 13) {
				this.buildWindow.house_build.gotoAndStop(11 + homeSkin);
				this.buildWindow.cover.gotoAndStop(floorSkin);
				this.buildWindow.miska.gotoAndStop(0);
				this.buildWindow.tree1.gotoAndStop(0);
				this.buildWindow.tree2.gotoAndStop(0);
				
				this.buildWindow.house_build.visible = true;
				this.buildWindow.cover.visible = true;
				this.buildWindow.miska.visible = false;
				this.buildWindow.tree1.visible = false;
				this.buildWindow.tree2.visible = false;
			}
			else if (bProgress == 14) {
				this.buildWindow.house_build.gotoAndStop(11 + homeSkin);
				this.buildWindow.cover.gotoAndStop(floorSkin);
				this.buildWindow.miska.gotoAndStop(miskSkin);
				this.buildWindow.tree1.gotoAndStop(0);
				this.buildWindow.tree2.gotoAndStop(0);
				
				this.buildWindow.house_build.visible = true;
				this.buildWindow.cover.visible = true;
				this.buildWindow.miska.visible = true;
				this.buildWindow.tree1.visible = false;
				this.buildWindow.tree2.visible = false;
			}
			else if (bProgress <= 19) {
				this.buildWindow.house_build.gotoAndStop(11 + homeSkin);
				this.buildWindow.cover.gotoAndStop(floorSkin);
				this.buildWindow.miska.gotoAndStop(miskSkin);
				this.buildWindow.tree1.gotoAndStop(bProgress - 15);
				this.buildWindow.tree2.gotoAndStop(0);
				
				this.buildWindow.house_build.visible = true;
				this.buildWindow.cover.visible = true;
				this.buildWindow.miska.visible = true;
				this.buildWindow.tree1.visible = true;
				this.buildWindow.tree2.visible = false;
			}
			else if (bProgress <= 24) {
				this.buildWindow.house_build.gotoAndStop(11 + homeSkin);
				this.buildWindow.cover.gotoAndStop(floorSkin);
				this.buildWindow.miska.gotoAndStop(miskSkin);
				this.buildWindow.tree1.gotoAndStop(4);
				this.buildWindow.tree2.gotoAndStop(bProgress - 20);
				
				this.buildWindow.house_build.visible = true;
				this.buildWindow.cover.visible = true;
				this.buildWindow.miska.visible = true;
				this.buildWindow.tree1.visible = true;
				this.buildWindow.tree2.visible = true;
			}
			else {
				this.buildWindow.house_build.gotoAndStop(11 + homeSkin);
				this.buildWindow.cover.gotoAndStop(floorSkin);
				this.buildWindow.miska.gotoAndStop(miskSkin);
				this.buildWindow.tree1.gotoAndStop(4);
				this.buildWindow.tree2.gotoAndStop(4);
				
				this.buildWindow.house_build.visible = true;
				this.buildWindow.cover.visible = true;
				this.buildWindow.miska.visible = true;
				this.buildWindow.tree1.visible = true;
				this.buildWindow.tree2.visible = true;
			}
		}
		
		
		this.buildWindow.buildB.addEventListener("click", buildBB.bind(this));
		function buildBB() {
			if (bcoins.gte(bbCost)) {
				bcoins = bcoins.sub(bbCost);
				bProgress += 1;
			}
		}
		
		this.buildWindow.house_build.addEventListener("click", changeHomeSkin.bind(this));
